600	//
601	// Large content is sharded across goroutines; output is byte-identical either
602	// way. See jsonlContent.
603	func JSONLContent(content string) (string, error) {
604		return jsonlContentImpl(content, String, concurrencySafeRedactor)
605	}
606	
607	// Whether a per-leaf redactor may be called from several goroutines at once.
608	//
609	// This is a property of the redactor, not of the entry point that supplies it,
610	// so it is passed explicitly rather than implied by which internal function a
611	// caller happens to reach: String is pure and shardable, while the OPF flow's
612	// collector closures accumulate into a shared map and slice and are not.
613	const (
614		concurrencySafeRedactor   = true
615		concurrencyUnsafeRedactor = false
616	)
617	
618	// jsonlContentImpl is the body of JSONLContent parameterized by a per-leaf
619	// redactor. JSONLContent passes String (regex layers only). The OPF-enabled
620	// flow uses two passes: one with a collector that records leaves and returns
621	// identity, one with a redactor that combines regex layers with cached OPF
622	// spans for the recorded leaves.
623	//
624	// concurrencySafe reports whether redactor tolerates concurrent calls; when it
625	// does, large content is sharded across goroutines.
626	func jsonlContentImpl(content string, redactor func(string) string, concurrencySafe bool) (string, error) {
627		if result, handled, err := redactSingleJSONValue(content, redactor); handled {
628			return result, err
629		}
630		lines := strings.Split(content, "\n")
631		if !concurrencySafe {
632			return redactJSONLLines(lines, redactor)
633		}
634		return redactJSONLLinesSharded(lines, redactor)
635	}
636	
637	// redactSingleJSONValue handles the case where the whole content is one JSON
638	// value (e.g. pretty-printed single objects like OpenCode export) so
639	// field-aware redaction is used instead of falling back to entropy-based
640	// detection on raw text lines, which would corrupt high-entropy identifiers.
641	//
642	// handled is false when the content is JSONL, so the caller processes it line by
643	// line. Neither the shard split nor the incremental prefix cache in
644	// checkpoint/redact_cache.go applies to the single-value shape.
645	func redactSingleJSONValue(content string, redactor func(string) string) (result string, handled bool, err error) {
646		trimmed := strings.TrimSpace(content)
647		if len(trimmed) == 0 {
648			return "", false, nil
649		}
650		parsed, ok := parseSingleJSONValue(trimmed)
651		if !ok {
652			return "", false, nil
653		}
654		result, err = applyJSONReplacements(content, collectJSONLReplacements(parsed, redactor))
655		if err != nil {
656			return "", true, err
657		}
658		return result, true, nil
659	}
660	
661	// IsLineDelimited reports whether JSONLContent will redact content line by line
662	// rather than as a single JSON value.
663	//
664	// Callers that split content and redact the pieces separately MUST check this
665	// first. The line path composes -- redact(A+B) == redact(A)+redact(B) for
666	// newline-terminated A -- because each line is redacted in isolation. The
667	// single-JSON-value path does NOT: it is field-aware across the whole document,
668	// so redacting a fragment of it instead falls back to raw regex and entropy
669	// detection over partial JSON, which is the identifier corruption
670	// redactSingleJSONValue exists to avoid.
671	//
672	// A filename is not a safe proxy for this. OpenCode writes a single JSON object
673	// to the same full.jsonl path that other agents write JSONL to.
674	func IsLineDelimited(content []byte) bool {
675		trimmed := bytes.TrimSpace(content)
676		if len(trimmed) == 0 {
677			return false
678		}
679		// Decode stops at the first complete value, so this does not scan a large
680		// JSONL body. Content that is not JSON at all still goes down the line path,
681		// where each line is redacted independently.
682		dec := json.NewDecoder(bytes.NewReader(trimmed))
683		var parsed any
684		if err := dec.Decode(&parsed); err != nil {
685			return true
686		}
687		return !isSingleJSONValue(dec)
688	}
689	
690	// parseSingleJSONValue reports whether s decodes as exactly one JSON value.
691	//
692	// Uses a streaming decoder so a large JSONL input is not copied: Decode stops at
693	// the first complete value, then isSingleJSONValue checks for a second one. A
694	// decode failure is a routing signal, not an error — it just means the content
695	// is not a single JSON value.
696	func parseSingleJSONValue(s string) (any, bool) {
697		dec := json.NewDecoder(strings.NewReader(s))
698		var parsed any
699		if err := dec.Decode(&parsed); err != nil {
700			return nil, false
701		}
702		return parsed, isSingleJSONValue(dec)
703	}
704	
705	// jsonlShardTargetBytes is the rough content size per shard, and hence also the
706	// sharding threshold: content under 2x this yields fewer than two shards and
707	// runs sequentially.
708	//
709	// The win is not purely parallelism: redaction cost per byte climbs with input
710	// size (allocation and GC pressure over one large buffer), so cutting the
711	// content into small pieces is cheaper per byte *and* lets pieces run
712	// concurrently. Measured on a 20MB Codex transcript: 43s sequential vs 2.1s
713	// across 12 shards. Hence a byte-sized shard target rather than one shard per
714	// core, with worker count bounding actual concurrency.
715	const jsonlShardTargetBytes = 1 << 20 // 1MiB
716	
717	// redactJSONLLinesSharded splits lines into contiguous byte-balanced groups,
718	// redacts them concurrently, and rejoins them in order. Output is byte-identical
719	// to redactJSONLLines over the same lines, because each line is redacted in
720	// isolation and shard boundaries fall between lines.
721	//
722	// redactor MUST be safe for concurrent use.
723	func redactJSONLLinesSharded(lines []string, redactor func(string) string) (string, error) {
724		// Balance shards by bytes, not by line count: agent transcripts mix
725		// thousands of short lines with occasional multi-MB tool results, so equal
726		// line counts would leave one oversized shard as the tail.
727		bounds := shardLineBounds(lines, jsonlShardTargetBytes)
728		if len(bounds) < 2 {
729			return redactJSONLLines(lines, redactor)
730		}
731	
732		results := make([]string, len(bounds))
733		g := new(errgroup.Group)
734		g.SetLimit(runtime.GOMAXPROCS(0))
735		for i, b := range bounds {
736			g.Go(func() error {
737				out, err := redactJSONLLines(lines[b.lo:b.hi], redactor)
738				if err != nil {
739					return err
740				}
741				results[i] = out
742				return nil
743			})
744		}
745		if err := g.Wait(); err != nil {
746			return "", fmt.Errorf("redacting JSONL shard: %w", err)
747		}
748	
749		// Shards are contiguous line ranges, so rejoining them with "\n" in order
750		// reproduces the sequential join exactly.
751		return strings.Join(results, "\n"), nil
752	}
753	
754	// lineRange is a half-open range of line indexes forming one shard.
755	type lineRange struct{ lo, hi int }
756	
757	// shardLineBounds groups lines into contiguous ranges of roughly targetBytes
758	// each. A single line larger than targetBytes becomes its own shard rather than
759	// being split, since lines are the indivisible unit of redaction.
760	func shardLineBounds(lines []string, targetBytes int) []lineRange {
761		var bounds []lineRange
762		lo, running := 0, 0
763		for i, line := range lines {
764			running += len(line) + 1 // +1 for the rejoined newline
765			if running >= targetBytes && i+1 < len(lines) {
766				bounds = append(bounds, lineRange{lo: lo, hi: i + 1})
767				lo, running = i+1, 0
768			}
769		}
770		if lo < len(lines) {
771			bounds = append(bounds, lineRange{lo: lo, hi: len(lines)})
772		}
773		return bounds
774	}
775	
776	// redactJSONLLines redacts each line independently and rejoins them with "\n".
777	//
778	// Every line is handled in isolation: no state carries between lines, which is
779	// what makes sharding across goroutines (jsonlContentConcurrent) produce
780	// byte-identical output to a sequential pass. Keep it that way — a redactor or
781	// line rule that depended on earlier lines would silently break that guarantee.
782	func redactJSONLLines(lines []string, redactor func(string) string) (string, error) {
783		var b strings.Builder
784		// Redaction only ever shrinks or preserves length, so the input size is a
785		// sound capacity estimate and avoids repeated doubling of a large buffer.
786		size := len(lines) - 1
787		for _, line := range lines {
788			size += len(line)
789		}
790		if size > 0 {
791			b.Grow(size)
792		}
793		for i, line := range lines {
794			if i > 0 {
795				b.WriteByte('\n')
796			}
797			lineTrimmed := strings.TrimSpace(line)
798			if lineTrimmed == "" {
799				b.WriteString(line)
800				continue
801			}
802			var parsed any
803			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
804				b.WriteString(redactor(line))
805				continue
806			}
807			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed, redactor))
808			if err != nil {
809				return "", err
810			}
811			b.WriteString(result)
812		}
813		return b.String(), nil
814	}
