816	// StringWithPrivacyFilter augments String with the OpenAI Privacy Filter.
817	// Use only at condensation/export boundaries; per-turn writes must use
818	// String to avoid the OPF shell-out cost inside the agent loop.
819	func StringWithPrivacyFilter(ctx context.Context, s string) string {
820		regions := detectAllLayers(s)
821		regions = append(regions, detectOPF(ctx, getOPFConfig(), s)...)
822		return applyRegions(s, regions)
823	}
