825	// JSONLContentWithPrivacyFilter augments JSONLContent with the OpenAI
826	// Privacy Filter via batched inference. Walks the content twice: pass 1
827	// collects unique prose-shaped leaves into a single RedactBatch call;
828	// pass 2 applies the eight regex layers per leaf plus the cached OPF spans
829	// for that leaf. One OPF shell-out covers the whole transcript instead of
830	// one per leaf — without batching, a typical 500-leaf transcript would
831	// take many minutes per commit.
832	//
833	// Falls back to the plain JSONLContent flow when OPF is unconfigured, the
834	// breaker is tripped, no categories are enabled, or the batch call errors.
835	func JSONLContentWithPrivacyFilter(ctx context.Context, content string) (string, error) {
836		cfg := getOPFConfig()
837		if cfg == nil || !cfg.Enabled || cfg.runtime == nil || opfBreakerTripped.Load() {
838			return jsonlContentImpl(content, String, concurrencySafeRedactor)
839		}
840		cats := enabledCategories(cfg)
841		if len(cats) == 0 {
842			return jsonlContentImpl(content, String, concurrencySafeRedactor)
843		}
844	
845		// Pass 1: collect eligible (has-space, deduped) leaves. The collector
846		// closure returns identity so the JSONL walker doesn't mutate content.
847		seen := make(map[string]struct{})
848		var inputs []string
849		if _, err := jsonlContentImpl(content, func(v string) string {
850			if strings.ContainsRune(v, ' ') {
851				if _, ok := seen[v]; !ok {
852					seen[v] = struct{}{}
853					inputs = append(inputs, v)
854				}
855			}
856			return v
857		}, concurrencyUnsafeRedactor); err != nil {
858			return "", err
859		}
860	
861		// Pass 2: single batched OPF call.
862		spansByInput := make(map[string][]Span, len(inputs))
863		if len(inputs) > 0 {
864			fmt.Fprintln(opfStderr, "→ OpenAI Privacy Filter: scanning transcript…")
865			start := time.Now()
866			batched, err := cfg.runtime.RedactBatch(ctx, inputs, cats)
867			if err != nil {
868				handleOPFFailure(ctx, cfg, err)
869				return jsonlContentImpl(content, String, concurrencySafeRedactor)
870			}
871			fmt.Fprintf(opfStderr, "✓ OpenAI Privacy Filter: done (%.1fs)\n", time.Since(start).Seconds())
872			// A short return means the runtime gave us fewer span slices than
873			// inputs — the tail leaves would receive zero OPF spans and the
874			// caller would proceed as if OPF had found nothing. That silently
875			// produces under-redacted output and is indistinguishable from a
876			// "no PII present" result. Treat as a runtime contract violation:
877			// trip the breaker so the pre-push rewrite's post-loop
878			// OPFBreakerTripped() check aborts before the Entire-OPF-Applied
879			// trailer can be attached to under-redacted commits. The production
880			// shell-out always returns len(inputs), so this only fires for a
881			// misbehaving custom runtime — but the cost of leaving it dormant
882			// is too high for a privacy contract.
883			if len(batched) != len(inputs) {
884				shortErr := fmt.Errorf("opf runtime returned %d span slices for %d inputs", len(batched), len(inputs))
885				handleOPFFailure(ctx, cfg, shortErr)
886				return jsonlContentImpl(content, String, concurrencySafeRedactor)
887			}
888			for i, in := range inputs {
889				spansByInput[in] = batched[i]
890			}
891		}
892	
893		// Pass 3: per-leaf regex layers + cached OPF spans.
894		return jsonlContentImpl(content, func(v string) string {
895			regions := detectAllLayers(v)
896			regions = append(regions, opfSpanRegions(v, spansByInput[v], cfg)...)
897			return applyRegions(v, regions)
898		}, concurrencySafeRedactor)
899	}
