901	// applyJSONReplacements applies collected (original, redacted) string pairs
902	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
903	// Returns s unchanged if repls is empty.
904	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
905		if len(repls) == 0 {
906			return s, nil
907		}
908		for _, r := range repls {
909			origJSON, err := jsonEncodeString(r.original)
910			if err != nil {
911				return "", err
912			}
913			replJSON, err := jsonEncodeString(r.redacted)
914			if err != nil {
915				return "", err
916			}
917			if r.key == "" {
918				s = strings.ReplaceAll(s, origJSON, replJSON)
919				continue
920			}
921			keyJSON, err := jsonEncodeString(r.key)
922			if err != nil {
923				return "", err
924			}
925			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
926		}
927		return s, nil
928	}
929	
930	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
931	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
932	// substitution to value positions so a key's own redacted text is not
933	// rewritten when it collides with another field's value.
934	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
935		if !strings.Contains(s, keyJSON) {
936			return s
937		}
938		var b strings.Builder
939		b.Grow(len(s))
940		i := 0
941		for i < len(s) {
942			j := strings.Index(s[i:], keyJSON)
943			if j < 0 {
944				b.WriteString(s[i:])
945				break
946			}
947			keyEnd := i + j + len(keyJSON)
948			b.WriteString(s[i : i+j])
949			b.WriteString(keyJSON)
950			p := keyEnd
951			for p < len(s) && isJSONWhitespace(s[p]) {
952				p++
953			}
954			if p >= len(s) || s[p] != ':' {
955				i = keyEnd
956				continue
957			}
958			p++
959			for p < len(s) && isJSONWhitespace(s[p]) {
960				p++
961			}
962			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
963				b.WriteString(s[keyEnd:p])
964				b.WriteString(replJSON)
965				i = p + len(origJSON)
966				continue
967			}
968			i = keyEnd
969		}
970		return b.String()
971	}
972	
973	func isJSONWhitespace(c byte) bool {
974		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
975	}
976	
977	// isSingleJSONValue returns true if the decoder has reached EOF (no more
978	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
979	// object) from JSONL (multiple concatenated values). We attempt a second Decode
980	// and require io.EOF rather than relying on dec.More(), which is documented for
981	// use inside arrays/objects and not for top-level value boundaries.
982	func isSingleJSONValue(dec *json.Decoder) bool {
983		var discard json.RawMessage
984		return dec.Decode(&discard) == io.EOF
985	}
