987	// collectJSONLReplacements walks a parsed JSON value and collects unique
988	// string replacements via the supplied per-leaf redactor. JSONLContent
989	// passes String; the OPF-enabled flow passes a closure that combines the
990	// regex layers with cached batched OPF spans.
991	func collectJSONLReplacements(v any, redactor func(string) string) []jsonReplacement {
992		seen := make(map[string]bool)
993		var repls []jsonReplacement
994		var walk func(key string, credentialContext bool, v any)
995		walk = func(key string, credentialContext bool, v any) {
996			switch val := v.(type) {
997			case map[string]any:
998				if shouldSkipJSONLObject(val) {
999					return
1000				}
1001				childCredentialContext := credentialContext || isCredentialJSONObject(val)
1002				for k, child := range val {
1003					if shouldSkipJSONLField(k) {
1004						continue
1005					}
1006					walk(k, childCredentialContext, child)
1007				}
1008			case []any:
1009				for _, child := range val {
1010					walk("", credentialContext, child)
1011				}
1012			case string:
1013				redacted := redactor(val)
1014				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
1015					redacted = RedactedPlaceholder
1016				}
1017				if redacted != val {
1018					seenKey := key + "\x00" + val
1019					if !seen[seenKey] {
1020						seen[seenKey] = true
1021						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
1022					}
1023				}
1024			}
1025		}
1026		walk("", false, v)
1027		return repls
1028	}
