1030	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
1031	// Skips signature fields (any key ending in "signature"), ID fields (ending in "id"/"ids"),
1032	// and common path/directory fields.
1033	func shouldSkipJSONLField(key string) bool {
1034		lower := strings.ToLower(key)
1035	
1036		// Skip signature fields: cryptographic attestations, not secrets. Covers
1037		// "signature" (Claude Code) and provider variants like "thinkingSignature"
1038		// (Oh My Pi). Their values are high-entropy base64, so the entropy scanner
1039		// would otherwise redact them — corrupting extended-thinking signatures and
1040		// breaking transcript replay ("Invalid `signature` in `thinking` block").
1041		if strings.HasSuffix(lower, "signature") {
1042			return true
1043		}
1044	
1045		// Skip ID fields
1046		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
1047			return true
1048		}
1049	
1050		// Skip common path and directory fields from agent transcripts.
1051		// These appear frequently in tool calls and are structural, not secrets.
1052		switch lower {
1053		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
1054			return true
1055		}
1056	
1057		return false
1058	}
1059	
1060	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
1061	func shouldSkipJSONLObject(obj map[string]any) bool {
1062		t, ok := obj["type"].(string)
1063		return ok && (strings.HasPrefix(t, "image") || t == "base64")
1064	}
