1066	func shannonEntropy(s string) float64 {
1067		if len(s) == 0 {
1068			return 0
1069		}
1070		freq := make(map[byte]int)
1071		for i := range len(s) {
1072			freq[s[i]]++
1073		}
1074		length := float64(len(s))
1075		var entropy float64
1076		for _, count := range freq {
1077			p := float64(count) / length
1078			entropy -= p * math.Log2(p)
1079		}
1080		return entropy
1081	}
1082	
1083	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
1084	func jsonEncodeString(s string) (string, error) {
1085		var buf bytes.Buffer
1086		enc := json.NewEncoder(&buf)
1087		enc.SetEscapeHTML(false)
1088		if err := enc.Encode(s); err != nil {
1089			return "", fmt.Errorf("json encode string: %w", err)
1090		}
1091		return strings.TrimSuffix(buf.String(), "\n"), nil
1092	}
