161	// String replaces secrets and PII in s using layered detection:
162	//  1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
163	//  2. Pattern-based: scanner engines selected via ConfigureScanners —
164	//     betterleaks regex rules (several hundred known secret formats) and/or the
165	//     goredact engine; betterleaks-only when unconfigured
166	//  3. Provider token prefixes: deterministic prefix rules for credential
167	//     formats betterleaks misses in isolation (e.g. Supabase sb_secret_)
168	//  4. Credentialed URIs: URLs containing userinfo passwords
169	//  5. Database connection strings: JDBC, keyword DSNs, and semicolon strings
170	//  6. User-defined custom rules: configured via ConfigureCustomRules
171	//  7. Bounded credential key/value pairs: DB_PASSWORD=...
172	//  8. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
173	//
174	// A string is redacted if ANY method flags it.
175	func String(s string) string {
176		return applyRegions(s, detectAllLayers(s))
177	}
178	
179	// detectAllLayers runs the always-on, opt-in, and scanner-configurable
180	// detection layers and returns their tagged regions. The OpenAI Privacy Filter
181	// (the final, network-backed layer) is NOT included — callers that want it
182	// append detectOPF spans to the result before passing to applyRegions. See
183	// StringWithPrivacyFilter for the augmented flow.
184	func detectAllLayers(s string) []taggedRegion {
185		var regions []taggedRegion
186	
187		// 1. Entropy-based detection (secrets — always on).
188		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
189			start, end := loc[0], loc[1]
190	
191			// Don't consume characters that are part of JSON/string escape sequences.
192			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
193			// (consuming the 'n' from '\n'), and after replacement the '\' would be
194			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
195			// Only skip for known JSON escape letters to avoid trimming real secrets
196			// that happen to follow a literal backslash in decoded content.
197			if start > 0 && s[start-1] == '\\' {
198				switch s[start] {
199				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
200					start++
201					if end-start < 10 {
202						continue
203					}
204				}
205			}
206	
207			if shannonEntropy(s[start:end]) > entropyThreshold {
208				regions = append(regions, taggedRegion{region: region{start, end}})
209			}
210		}
211	
212		// 2. Pattern-based detection via scanner engines (secrets — selected
213		// via ConfigureScanners; betterleaks-only when unconfigured).
214		if getScanners().betterleaks {
215			if d := getDetector(); d != nil {
216				seenSecrets := make(map[string]struct{})
217				for _, f := range d.DetectString(s) {
218					// Placeholder-valued findings (changeme, secret_here, mask runs)
219					// stay visible — but only on an exact match: splitting a greedy
220					// finding at a placeholder head can leak a real secret in the tail.
221					if isPlaceholderSecretValue(f.Secret) {
222						continue
223					}
224					// A finding reports one occurrence, but the search below already
225					// covers every copy of its secret. Repeated findings must not
226					// rescan the input and accumulate quadratically many regions.
227					if _, seen := seenSecrets[f.Secret]; seen {
228						continue
229					}
230					seenSecrets[f.Secret] = struct{}{}
231					searchFrom := 0
232					for {
233						idx := strings.Index(s[searchFrom:], f.Secret)
234						if idx < 0 {
235							break
236						}
237						absIdx := searchFrom + idx
238						regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
239						searchFrom = absIdx + len(f.Secret)

