17	// buildGenerateArgs assembles the claude CLI argv for a --print text-generation
18	// call.
19	//
20	// The subprocess must stay isolated from the user's project/local AND user
21	// settings: loading them would fire user-level hooks and, worse, honor
22	// user-level tool permissions (e.g. permissions.defaultMode=bypassPermissions),
23	// which would let prompt-injection in the untrusted dispatch data drive tool
24	// execution. So we pass --setting-sources "" (load nothing).
25	//
26	// The one thing we genuinely need from the user settings is auth. Users on API
27	// billing configure it with `apiKeyHelper` (a command that prints the key),
28	// which lives in user settings and is therefore dropped by --setting-sources "".
29	// Rather than load the whole settings file back (and re-inherit hooks and
30	// permissions), we extract only apiKeyHelper and re-inject it via a --settings
31	// file (settingsPath), so auth works while nothing else from the user's settings
32	// is loaded.
33	//
34	// The injected settings are passed as a file path, not an inline JSON string:
35	// apiKeyHelper can embed a literal key, and an inline value would land in the
36	// process argv (visible via ps / /proc/<pid>/cmdline / EDR tooling). The file is
37	// written 0600 (see writeAuthSettingsFile), matching settings.json's protection.
38	//
39	// Auth methods that do not live in user settings — an exported ANTHROPIC_API_KEY
40	// (survives StripGitEnv) and keychain/subscription credentials — keep working
41	// without any injection (settingsPath == "").
42	func buildGenerateArgs(model, settingsPath string) []string {
43		args := []string{
44			"--print", "--output-format", "json",
45			"--model", model,
46			"--setting-sources", "",
47		}
48		if settingsPath != "" {
49			args = append(args, "--settings", settingsPath)
50		}
51		return args
52	}
53	
54	// buildStreamingGenerateArgs is buildGenerateArgs for the stream-json path,
55	// with the same isolation and auth-injection contract (see buildGenerateArgs).
56	// --include-partial-messages enables the per-token stream_event envelopes
57	// that PhaseFirstToken and PhaseGenerating are dispatched from, and
58	// --verbose is required by the claude CLI for stream-json output.
59	func buildStreamingGenerateArgs(model, settingsPath string) []string {
60		args := []string{
61			"--print",
62			"--output-format", "stream-json",
63			"--include-partial-messages",
64			"--verbose",
65			"--model", model,
66			"--setting-sources", "",
67		}
68		if settingsPath != "" {
69			args = append(args, "--settings", settingsPath)
70		}
71		return args
72	}
