74	// writeAuthSettingsFile writes a minimal claude settings file containing only
75	// the given apiKeyHelper and returns its path plus a cleanup func. The file is
76	// created 0600 so the (possibly key-bearing) helper is no more exposed than the
77	// user's own settings.json. Returns ("", nil, nil) when apiKeyHelper is empty.
78	func writeAuthSettingsFile(apiKeyHelper string) (string, func(), error) {
79		if strings.TrimSpace(apiKeyHelper) == "" {
80			return "", nil, nil
81		}
82		data, err := json.Marshal(map[string]string{"apiKeyHelper": apiKeyHelper})
83		if err != nil {
84			return "", nil, fmt.Errorf("marshal auth settings: %w", err)
85		}
86		f, err := os.CreateTemp("", "entire-claude-auth-*.json") // 0600 by default
87		if err != nil {
88			return "", nil, fmt.Errorf("create auth settings file: %w", err)
89		}
90		path := f.Name()
91		cleanup := func() { _ = os.Remove(path) }
92		if _, err := f.Write(data); err != nil {
93			_ = f.Close()
94			cleanup()
95			return "", nil, fmt.Errorf("write auth settings file: %w", err)
96		}
97		if err := f.Close(); err != nil {
98			cleanup()
99			return "", nil, fmt.Errorf("close auth settings file: %w", err)
100		}
101		return path, cleanup, nil
102	}
