104	// userClaudeSettingsPath resolves the user's claude settings.json the same way
105	// the claude CLI does: $CLAUDE_CONFIG_DIR/settings.json when set, otherwise
106	// ~/.claude/settings.json.
107	func userClaudeSettingsPath() (string, error) {
108		if dir := strings.TrimSpace(os.Getenv("CLAUDE_CONFIG_DIR")); dir != "" {
109			return filepath.Join(dir, "settings.json"), nil
110		}
111		home, err := os.UserHomeDir()
112		if err != nil {
113			return "", fmt.Errorf("resolve home directory: %w", err)
114		}
115		return filepath.Join(home, ".claude", "settings.json"), nil
116	}
