118	// readUserAPIKeyHelper returns the apiKeyHelper field from the user's claude
119	// settings, or "" if absent. Best-effort: a missing file or malformed JSON
120	// yields "" so we fall back to env/keychain auth rather than failing.
121	func readUserAPIKeyHelper() string {
122		path, err := userClaudeSettingsPath()
123		if err != nil {
124			return ""
125		}
126		data, err := os.ReadFile(path) //nolint:gosec // path is the user's own claude config, not attacker-controlled
127		if err != nil {
128			return ""
129		}
130		var settings struct {
131			APIKeyHelper string `json:"apiKeyHelper"`
132		}
133		if err := json.Unmarshal(data, &settings); err != nil {
134			return ""
135		}
136		return strings.TrimSpace(settings.APIKeyHelper)
137	}
