139	// GenerateText sends a prompt to the Claude CLI and returns the raw text response.
140	// Implements the agent.TextGenerator interface.
141	// The model parameter hints which model to use (e.g., "haiku", "sonnet").
142	// If empty, defaults to "haiku" for fast, cheap generation.
143	//
144	// Unlike most agents, this implementation runs the subprocess directly rather
145	// than through agent.RunIsolatedTextGeneratorCLI. The shared helper collapses
146	// stderr + exit code into a single formatted error string, but Claude CLI
147	// returns operational errors (auth, rate limit, invalid model) as exit 0
148	// with is_error:true in the JSON envelope on stdout — so we need structured
149	// access to stdout, stderr and the exit code to produce the typed ClaudeError
150	// values that formatCheckpointSummaryError maps to actionable messages.
151	func (c *ClaudeCodeAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
152		claudePath := "claude"
153		if model == "" {
154			model = "haiku"
155		}
156	
157		commandRunner := c.CommandRunner
158		if commandRunner == nil {
159			commandRunner = exec.CommandContext
160		}
161	
162		// Run isolated from all setting sources (see buildGenerateArgs), re-injecting
163		// only the user's apiKeyHelper (via a 0600 file, never argv) so API-billing
164		// auth keeps working without re-inheriting user hooks or tool permissions.
165		// Best-effort: if extracting/writing the helper fails, fall back to running
166		// without it (env/keychain auth still work) rather than failing the call.
167		settingsPath, cleanup, err := writeAuthSettingsFile(readUserAPIKeyHelper())
168		if err != nil {
169			settingsPath = ""
170		}
171		if cleanup != nil {
172			defer cleanup()
173		}
174	
175		cmd := commandRunner(ctx, claudePath, buildGenerateArgs(model, settingsPath)...)
176	
177		// Isolate from the user's git repo to prevent recursive hook triggers
178		// and index pollution (matches agent.RunIsolatedTextGeneratorCLI behavior).
179		cmd.Dir = os.TempDir()
180		cmd.Env = agent.StripGitEnv(os.Environ())
181		cmd.Stdin = strings.NewReader(prompt)
182	
183		var stdout, stderr bytes.Buffer
184		cmd.Stdout = &stdout
185		cmd.Stderr = &stderr
186	
187		if err := cmd.Run(); err != nil {
188			// Prefer a structured Claude error over bare ctx sentinels: if the CLI
189			// already emitted an is_error envelope on stdout, surface that even when
190			// the context happens to be done. Otherwise the user loses actionable
191			// auth/rate-limit/config diagnostics whenever ctx and the subprocess
192			// both fail at roughly the same time.
193			if _, env, parseErr := parseGenerateTextResponse(stdout.Bytes()); parseErr == nil && env != nil && env.IsError {
194				result := ""
195				if env.Result != nil {
196					result = *env.Result
197				}
198				exitCode := 0
199				var exitErr *exec.ExitError
200				if errors.As(err, &exitErr) {
201					exitCode = exitErr.ExitCode()
202				}
203				return "", classifyEnvelopeError(result, env.APIErrorStatus, exitCode)
204			}
205			// No structured signal on stdout — ctx cancellation is next most
206			// informative, since the rest is a guess. Wrap the sentinel in a
207			// *agent.TextGenerationError (like the streaming path and every other
208			// provider) so the explain timeout diagnostic still gets captured
209			// stderr and the stdout byte count when this path is reached via the
210			// old-CLI streaming fallback.
211			if ctxErr := ctx.Err(); ctxErr != nil && (errors.Is(ctxErr, context.DeadlineExceeded) || errors.Is(ctxErr, context.Canceled)) {
212				sentinel := context.Canceled
213				if errors.Is(ctxErr, context.DeadlineExceeded) {
214					sentinel = context.DeadlineExceeded
215				}
216				return "", &agent.TextGenerationError{
217					Err:         sentinel,
218					Stderr:      strings.TrimSpace(stderr.String()),
219					StdoutBytes: stdout.Len(),
220				}
221			}
222			if isExecNotFound(err) {
223				return "", &ClaudeError{Kind: ClaudeErrorCLIMissing, Cause: err}
224			}
225			exitCode := -1
226			var exitErr *exec.ExitError
227			if errors.As(err, &exitErr) {
228				exitCode = exitErr.ExitCode()
229			}
230			return "", classifyStderrError(stderr.String(), exitCode)
231		}
232	
233		// Exit 0: parse the response and check for is_error (Claude CLI returns
234		// most operational errors as exit 0 with is_error:true in the envelope).
235		result, env, err := parseGenerateTextResponse(stdout.Bytes())
236		if err != nil {
237			return "", &ClaudeError{Kind: ClaudeErrorUnknown, Message: fmt.Sprintf("failed to parse claude CLI response: %v", err), Cause: err}
238		}
239		if env != nil && env.IsError {
240			return "", classifyEnvelopeError(result, env.APIErrorStatus, 0)
241		}
242	
243		return result, nil
244	}
245	
246	// isExecNotFound returns true only when err indicates the binary was not
247	// found on PATH or at the given absolute path. It intentionally excludes
248	// other *exec.Error causes (permission denied, invalid executable format),
249	// which should surface as a generic failure so operators aren't misdirected
250	// to a reinstall when the real problem is a broken/inaccessible binary.
251	func isExecNotFound(err error) bool {
252		var execErr *exec.Error
253		if errors.As(err, &execErr) && errors.Is(execErr.Err, exec.ErrNotFound) {
254			return true
255		}
256		return errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist)
257	}
