1536	// validateOPFSettings rejects unknown category names so typos surface at
1537	// parse time. Silent zero-detection of a privacy category is effectively
1538	// a correctness bug — the user thinks they're protected but they're not.
1539	func validateOPFSettings(opf *OPFSettings) error {
1540		if opf == nil {
1541			return nil
1542		}
