1545				return fmt.Errorf("openai_privacy_filter.categories has unknown key %q (see docs/security-and-privacy.md for the supported set)", name)
1546			}
1547		}
1548		if opf.TimeoutSeconds < 0 {
1549			return fmt.Errorf("openai_privacy_filter.timeout_seconds must be greater than or equal to 0 (got %d)", opf.TimeoutSeconds)
1550		}
1551		switch opf.PromptDefault {
1552		case "", OPFPromptAsk, OPFPromptNever, OPFPromptAlways:
1553			// ok
1554		default:
1555			return fmt.Errorf("openai_privacy_filter.prompt_default must be one of %q, %q, %q (got %q)",
1556				OPFPromptAsk, OPFPromptNever, OPFPromptAlways, opf.PromptDefault)
1557		}
1558		return nil
1559	}
