106	// hasMultipleSessions reports whether the points span more than one session,
107	// which controls whether per-line session identifiers are shown.
108	func hasMultipleSessions(points []strategy.PendingCheckpoint) bool {
109		sessionIDs := make(map[string]bool)
110		for _, p := range points {
