118	// pendingCheckpointLabel renders a single pending checkpoint as a display label for the
119	// `checkpoint list --pending` human view. When hasMultipleSessions is true, a
120	// sanitized session prompt is appended to help disambiguate concurrent
121	// sessions.
122	func pendingCheckpointLabel(p strategy.PendingCheckpoint, hasMultipleSessions bool) string {
123		timestamp := p.Date.Format("2006-01-02 15:04")
124	
125		sessionLabel := ""
126		if hasMultipleSessions && p.SessionPrompt != "" {
127			sessionLabel = fmt.Sprintf(" [%s]", sanitizeForTerminal(p.SessionPrompt))
128		}
129	
130		switch {
131		case p.IsLogsOnly:
132			// Committed checkpoint - show commit sha (this is the real user commit)
133			shortID := p.ID
134			if len(shortID) >= 7 {
135				shortID = shortID[:7]
136			}
137			return fmt.Sprintf("%s (%s) %s%s", shortID, timestamp, sanitizeForTerminal(p.Message), sessionLabel)
138		case p.IsTaskCheckpoint:
139			// Task checkpoint (uncommitted) - no sha shown
140			return fmt.Sprintf("        (%s) [Task] %s%s", timestamp, sanitizeForTerminal(p.Message), sessionLabel)
141		default:
142			// Shadow checkpoint (uncommitted) - no sha shown (internal commit)
143			return fmt.Sprintf("        (%s) %s%s", timestamp, sanitizeForTerminal(p.Message), sessionLabel)
144		}
145	}
