147	// sanitizeForTerminal removes or replaces characters that cause rendering issues
148	// in terminal UI components. This includes emojis with skin-tone modifiers and
149	// other multi-codepoint characters that confuse width calculations.
150	func sanitizeForTerminal(s string) string {
151		var result strings.Builder
152		result.Grow(len(s))
153	
154		for _, r := range s {
155			// Skip emoji skin tone modifiers (U+1F3FB to U+1F3FF)
156			if r >= 0x1F3FB && r <= 0x1F3FF {
157				continue
158			}
159			// Skip zero-width joiners used in emoji sequences
160			if r == 0x200D {
161				continue
162			}
163			// Skip variation selectors (U+FE00 to U+FE0F)
164			if r >= 0xFE00 && r <= 0xFE0F {
165				continue
166			}
167			// Keep printable characters and common whitespace
168			if unicode.IsPrint(r) || r == '\t' || r == '\n' {
169				result.WriteRune(r)
170			}
171		}
172	
173		return result.String()
174	}
