1	// Package tuiutil hosts width-aware text helpers for fixed-width TUI
2	// dashboards: ANSI/control-char stripping, display-width-based truncation
3	// and padding, and a compact duration formatter.
4	package tuiutil
5	
6	import (
7		"fmt"
8		"strings"
9		"time"
10		"unicode"
11	
12		"github.com/charmbracelet/x/ansi"
13	)
14	
15	// StripANSI removes ANSI escape sequences from s.
16	func StripANSI(s string) string {
17		return ansi.Strip(s)
18	}
19	
20	// SanitizeDisplayText strips ANSI escapes and control characters so the
21	// result is safe to render in a single-line table cell. Newlines and tabs
22	// collapse to a single space; carriage returns and other control runes are
23	// dropped entirely.
24	func SanitizeDisplayText(s string) string {
25		stripped := StripANSI(s)
26		return strings.Map(func(r rune) rune {
27			switch r {
28			case '\n', '\t':
29				return ' '
30			case '\r':
31				return -1
32			}
33			if unicode.IsControl(r) {
34				return -1
35			}
36			return r
37		}, stripped)
38	}
39	
40	// PadDisplayWidth truncates or right-pads s with spaces so its display
41	// width is exactly width cells (ANSI-aware).
42	func PadDisplayWidth(s string, width int) string {
43		return PadDisplayWidthWith(s, width, " ")
44	}
45	
46	// PadDisplayWidthWith truncates or right-pads s with the pad string so its
47	// display width is exactly width cells. Pad strings whose display width is
48	// not 1 fall back to space padding to keep alignment predictable.
49	func PadDisplayWidthWith(s string, width int, pad string) string {
50		s = TruncateDisplayWidth(s, width)
51		remaining := width - ansi.StringWidth(s)
52		if remaining <= 0 {
53			return s
54		}
55		if ansi.StringWidth(pad) != 1 {
56			return s + strings.Repeat(" ", remaining)
57		}
58		return s + strings.Repeat(pad, remaining)
59	}
