61	// TruncateDisplayWidth shortens s so its display width is at most width
62	// cells, appending "…" as an ellipsis when truncation happens. Width 0 or
63	// less returns the empty string; width 1 truncates without an ellipsis
64	// since the ellipsis would consume the whole budget.
65	func TruncateDisplayWidth(s string, width int) string {
66		if width <= 0 {
67			return ""
68		}
69		if ansi.StringWidth(s) <= width {
70			return s
71		}
72		if width == 1 {
73			return ansi.Truncate(s, width, "")
74		}
75		return ansi.Truncate(s, width, "…")
76	}
