78	// WrapDisplayWidth wraps s to lines no wider than width display cells.
79	// Embedded '\n' characters are honored as paragraph boundaries: each
80	// paragraph is sanitized (ANSI/control stripped) and wrapped independently.
81	// A paragraph that wraps to nothing still contributes an empty line,
82	// preserving blank-line structure between paragraphs.
83	//
84	// Trailing newlines are stripped before splitting so "text\n" yields a
85	// single line, not a phantom blank tail.
86	//
87	// Returns nil for width <= 0 or input that is empty (or only newlines).
88	func WrapDisplayWidth(s string, width int) []string {
89		if width <= 0 {
90			return nil
91		}
92		s = strings.TrimRight(s, "\n")
93		if s == "" {
94			return nil
95		}
96		paragraphs := strings.Split(s, "\n")
97		out := make([]string, 0, len(paragraphs))
98		for _, p := range paragraphs {
99			clean := SanitizeDisplayText(p)
100			if clean == "" {
101				out = append(out, "")
102				continue
103			}
104			wrapped := ansi.Wrap(clean, width, "")
105			out = append(out, strings.Split(wrapped, "\n")...)
106		}
107		return out
108	}
