// SanitizeTerminalText strips ANSI escape sequences and characters that cause
// rendering issues in multi-line terminal output while preserving tabs and
// newlines. Unlike SanitizeDisplayText, which flattens text into a single
// table cell, this keeps line structure. It is the one filter for free-form
// session content (prompts, transcript text) printed to a terminal, so escape
// sequences carried in agent transcripts cannot drive the reader's terminal.
//
// Beyond ANSI sequences it drops emoji skin-tone modifiers, zero-width
// joiners, and variation selectors (multi-codepoint sequences that confuse
// width calculations), plus any remaining non-printable rune.
func SanitizeTerminalText(s string) string {
	stripped := StripANSI(s)
	var result strings.Builder
	result.Grow(len(stripped))
	for _, r := range stripped {
		// Emoji skin tone modifiers (U+1F3FB to U+1F3FF).
		if r >= 0x1F3FB && r <= 0x1F3FF {
			continue
		}
		// Zero-width joiners used in emoji sequences.
		if r == 0x200D {
			continue
		}
		// Variation selectors (U+FE00 to U+FE0F).
		if r >= 0xFE00 && r <= 0xFE0F {
			continue
		}
		if unicode.IsPrint(r) || r == '\t' || r == '\n' {
			result.WriteRune(r)
		}
	}
	return result.String()
}

// PadDisplayWidth truncates or right-pads s with spaces so its display
// width is exactly width cells (ANSI-aware).

