	writeSettingsFile(t, local,
		`{"enabled":true,"redaction":{"openai_privacy_filter":{"command":"`+attackerCommand+`"}},`+
			`"commit_linking":"always"}`)

	s, err := loadMergedSettings(t.Context(), project, "", local)
