	reviewConfigType := reflect.TypeOf(ReviewConfig{})
	var found []string
	seen := map[reflect.Type]bool{}
	var walk func(tp reflect.Type, path string)
	walk = func(tp reflect.Type, path string) {
		switch tp.Kind() {
		case reflect.Pointer, reflect.Slice, reflect.Array:
			walk(tp.Elem(), path)
		case reflect.Map:
			walk(tp.Elem(), path+".*")
		case reflect.Struct:
