				return
			}
			if seen[tp] {
				return
			}
			seen[tp] = true
			for i := range tp.NumField() {
				f := tp.Field(i)
				name := strings.Split(f.Tag.Get("json"), ",")[0]
				if name == "" {
					name = f.Name
				}
				walk(f.Type, path+"."+name)
			}
		default:
		}
	}
	walk(reflect.TypeOf(EntireSettings{}), "")
